import json, glob, random, math, collections
P='/Users/angadbawa/Development/NeatHacks/data/processed/'
S='/private/tmp/claude-501/-Users-angadbawa-Development-NeatHacks/c5ba5514-6b9c-45ac-a8a8-6c64b13e7f3d/scratchpad/'
BUCKETS={'semantic_distance','taxonomy_collision','multi_capability','near_duplicate','ambiguity','none'}
REASONS={'wrong_domain','wrong_output','current_not_historical','destructive','missing_capability','other'}
CONF={'high','medium','low'}
rows=[json.loads(l) for l in open(P+'tasks_tagged.jsonl')]
judg={}
for f in sorted(glob.glob(S+'judg_*.json')):
    for j in json.load(open(f)):
        assert j['idx'] not in judg, j['idx']
        judg[j['idx']]=j
errs=[]
assert sorted(judg)==list(range(len(rows))), (len(judg), set(range(len(rows)))-set(judg))
out=[]
for i,r in enumerate(rows):
    j=judg[i]
    b=j['buckets']
    if not set(b)<=BUCKETS: errs.append((i,'bad bucket',b))
    if j['primary_bucket'] not in b: errs.append((i,'primary not in buckets'))
    if 'none' in b and len(b)>1: errs.append((i,'none with others'))
    if set(j['evidence'])!=set(b): errs.append((i,'evidence keys != buckets',set(j['evidence'])^set(b)))
    for c in j['confusers']:
        if c['reason'] not in REASONS: errs.append((i,'bad reason',c))
        ids={t for t in [c['tool_id']]}
        # confuser must not be a gold id
        if c['tool_id'] in r['gold_ids']: errs.append((i,'confuser is gold',c['tool_id']))
    if j['confidence'] not in CONF: errs.append((i,'bad conf'))
