        assert len(match)==1, (i,e['name'],len(match))
        p=match[0]
        if p['proposed_id'] is not None and p['proposed_id'] not in catalog: errs.append((i,'bad proposal id',p['proposed_id']))
        plist.append({'name':e['name'],'status':e['status'],'proposed_id':p['proposed_id'],
                      'confidence':p['confidence'],'reason':p['reason']})
    new['resolution_proposals']=plist
    out.append(new)
assert sum(len(props[i]) for i in props)==sum(len(x['resolution_proposals']) for x in out)
print('validation errors:',len(errs))
for e in errs: print('  ',e)
assert not errs
with open(P+'tasks_tagged.jsonl','w',encoding='utf-8') as f:
    for r in out: f.write(json.dumps(r,ensure_ascii=False)+'\n')

allb=collections.Counter(b for r in out for b in r['buckets'])
prim=collections.Counter(r['primary_bucket'] for r in out)
print('bucket counts (any):',dict(allb))
print('primary counts:',dict(prim))
print('confidence:',dict(collections.Counter(r['confidence'] for r in out)))
changed=sum(1 for r in out if 'prior_buckets' in r)
prim_changed=sum(1 for r in out if r['primary_bucket']!=r['prior_primary_bucket'])
print('tasks with bucket set changed:',changed,' primary changed:',prim_changed)
print('shared_name tasks:',sum(r['features']['shared_name'] for r in out))

# review queue
queue={}
for r in out:
    reasons=[]
    if r['confidence']!='high': reasons.append(f"confidence_{r['confidence']}")
    if not r['fully_resolved']: reasons.append('not_fully_resolved')
    if any(e['status']=='ambiguous' for e in r['resolution']): reasons.append('ambiguous_gold')
    if any(e['status']=='missing' for e in r['resolution']): reasons.append('missing_gold')
    if reasons: queue[r['task_id']]=reasons
rest=sorted(r['task_id'] for r in out if r['task_id'] not in queue)
k=round(0.10*len(rest))
rng=random.Random(0)
for t in rng.sample(rest,k): queue[t]=['random_sample_10pct']
print(f'queue: {len(queue)} tasks ({len(rest)} rest, sample k={k})')
rc=collections.Counter(x for v in queue.values() for x in v)
print('queue reasons:',dict(rc))
with open(P+'review_queue.jsonl','w',encoding='utf-8') as f:
    for r in out:
        if r['task_id'] not in queue: continue
        f.write(json.dumps({'task_id':r['task_id'],'question':r['question'],'reasons':queue[r['task_id']],
            'confidence':r['confidence'],'review_reason':r['review_reason'],'primary_bucket':r['primary_bucket'],
            'buckets':r['buckets'],'fully_resolved':r['fully_resolved'],'gold_ids':r['gold_ids'],
            'resolution_proposals':r['resolution_proposals']},ensure_ascii=False)+'\n')
